(() => {
  const game = window.DRIFTWING;
  if (!game || !game.ctx) throw new Error('journal-p3: window.DRIFTWING is missing');
  const { ctx, state } = game;
  const journal = ctx.systems.journal;
  const challenges = ctx.systems.challenges;
  if (!journal || !challenges) throw new Error('journal-p3: the journal or the challenge system is missing');
  const kit = {
    results: [],
    check(name, ok, detail) { const line = `${ok ? 'PASS' : 'FAIL'} ${name}: ${detail}`; kit.results.push(line); if (!ok) console.error(`[journal-p3 check] ${line}`); return line; },
    before: journal.getRecords(),
    spawn: { x: state.player.position.x, z: state.player.position.z, heading: state.player.heading },
    sleep: (ms) => new Promise((done) => setTimeout(done, ms)),
    /** Switches craft through the settings channel (as the picker does) and waits for the flight to follow. */
    async fly(craft) {
      ctx.settings.set('craft', craft);
      const started = performance.now();
      while (state.flight.craft !== craft && performance.now() - started < 15000) await kit.sleep(100);
      return state.flight.craft === craft;
    },
    /** A safe cruise point 400 m above the ground at the spawn, heading as at the start. */
    home() {
      const ground = Math.max(ctx.world.groundHeight(kit.spawn.x, kit.spawn.z), ctx.world.WATER_LEVEL);
      ctx.systems.flight.resetTo({ x: kit.spawn.x, y: ground + 400, z: kit.spawn.z, heading: kit.spawn.heading });
    },
    text: () => document.getElementById('dw-journal-body').innerText,
    section: (id) => document.querySelector(`#dw-journal-body [data-journal-section="${id}"]`),
    async jump(id) {
      const button = document.querySelector(`#dw-journal-body [data-journal-jump="${id}"]`);
      if (!button) return false;
      button.click();
      await kit.sleep(900);
      const section = kit.section(id);
      const body = document.getElementById('dw-journal-body').getBoundingClientRect();
      const top = section ? section.getBoundingClientRect().top - body.top : NaN;
      return top >= -2 && top < 40;
    },
  };
  window.__journalKit = kit;
  ctx.settings.set('timeFrozen', true);
  return `backend ${game.backend}; craft ${state.flight.craft}; seed ${state.seed}; figures ${Object.keys(kit.before.figures).length}, perches ${kit.before.perches.count}, worlds ${kit.before.worldsVisited.length}`;
})()

(async () => {
  const kit = window.__journalKit;
  const { ctx } = window.DRIFTWING;
  const switched = await kit.fly('aerobatic');
  kit.home();
  await kit.sleep(2500);
  const position = { x: ctx.state.player.position.x, y: ctx.state.player.position.y, z: ctx.state.player.position.z };
  ctx.bus.emitTyped('figureFlown', { figure: 'loop', score: 91.4, craft: 'aerobatic', position });
  ctx.bus.emitTyped('figureFlown', { figure: 'loop', score: 77, craft: 'aerobatic', position });
  ctx.bus.emitTyped('figureFlown', { figure: 'aileronRoll', score: 84, craft: 'aerobatic', position });
  const figures = ctx.systems.journal.getRecords().figures;
  const before = kit.before.figures;
  const loops = (figures.loop?.count ?? 0) - (before.loop?.count ?? 0);
  const rolls = (figures.aileronRoll?.count ?? 0) - (before.aileronRoll?.count ?? 0);
  return kit.check('figures: figureFlown counts each figure and keeps its best score', switched && loops === 2 && rolls === 1 && figures.loop.bestScore >= 91.4 && figures.aileronRoll.bestScore >= 84, JSON.stringify({ switched, loop: figures.loop, aileronRoll: figures.aileronRoll }));
})()

(async () => {
  const kit = window.__journalKit;
  const { ctx, state } = window.DRIFTWING;
  const skins = { ...(ctx.settings.get('craftSkins') || {}) };
  kit.skinsBefore = { ...skins };
  skins.eagle = 'dragon';
  ctx.settings.set('craftSkins', skins);
  const switched = await kit.fly('eagle');
  kit.home();
  await kit.sleep(3500);
  const position = { x: state.player.position.x, y: state.player.position.y, z: state.player.position.z };
  ctx.bus.emitTyped('perched', { craft: 'eagle', perchId: 'peak:journal-step', kind: 'peak', position, perched: true });
  ctx.bus.emitTyped('perched', { craft: 'eagle', perchId: 'peak:journal-step', kind: 'peak', position, perched: false });
  ctx.bus.emitTyped('perched', { craft: 'eagle', perchId: 'tree:journal-step', kind: 'tree', position, perched: true });
  const records = ctx.systems.journal.getRecords();
  const before = kit.before.perches;
  return [
    kit.check('perches: a settle counts the perch and its kind, a take-off does not', records.perches.count - before.count === 2 && records.perches.kinds.peak - before.kinds.peak === 1 && records.perches.kinds.tree - before.kinds.tree === 1, JSON.stringify(records.perches)),
    kit.check('craft: the dragon skin flies and its time is kept per skin', switched && state.flight.craftState.skin === 'dragon' && records.skinTime.eagle?.dragon > (kit.before.skinTime.eagle?.dragon ?? 0) + 2, JSON.stringify({ skin: state.flight.craftState.skin, skinTime: records.skinTime.eagle })),
  ].join(' | ');
})()

(async () => {
