(async () => {
  const kit = window.__journalKit;
  const { ctx, state } = window.DRIFTWING;
  const challenges = ctx.systems.challenges;
  const switched = await kit.fly('glider');
  kit.home();
  await kit.sleep(1500);
  const heading = state.player.heading;
  const fx = Math.sin(heading * Math.PI / 180);
  const fz = -Math.cos(heading * Math.PI / 180);
  const origin = { x: state.player.position.x, z: state.player.position.z };
  let floor = -Infinity;
  for (let along = 0; along <= 1400; along += 50) floor = Math.max(floor, ctx.world.groundHeight(origin.x + fx * along, origin.z + fz * along));
  const y = Math.max(floor, 0) + 220;
  const roles = ['start', 'finish'];
  const course = {
    id: 'journalSprint',
    name: 'Journal Sprint',
    gates: roles.map((role, index) => ({ id: `g${index}`, role, center: { x: origin.x + fx * (600 + index * 300), y, z: origin.z + fz * (600 + index * 300) }, normal: { x: fx, y: 0, z: fz }, up: { x: 0, y: 1, z: 0 }, shape: 'circle', radius: 30 })),
    medals: { gold: 1, silver: 2, bronze: 900 },
    missed: { mode: 'penalty', penaltySeconds: 5, outsideCrossing: 'miss', skipDistance: 150 },
    start: { mode: 'gate', promptRadius: 1500 },
  };
  kit.courseKey = `${state.seed}:journalSprint`;
  kit.clearCourse = () => {
    const stored = ctx.storage.read('driftwing-v2.challenges', null);
    if (stored && stored.courses && stored.courses[kit.courseKey]) {
      delete stored.courses[kit.courseKey];
      ctx.storage.write('driftwing-v2.challenges', stored);
    }
    ctx.storage.remove(`driftwing-v2.challengePath.${kit.courseKey}.glider`);
    challenges.reloadRecords();
  };
  kit.clearCourse();
  const medalsBefore = ctx.systems.journal.getMedals();
  const finished = [];
  ctx.bus.onTyped('challengeFinished', (payload) => finished.push(payload));
  challenges.register(course, { owner: 'journal-p3 step' });
  for (const index of [0, 1]) {
    const gate = course.gates[index];
    ctx.systems.flight.resetTo({ x: gate.center.x - fx * 90, y: gate.center.y, z: gate.center.z - fz * 90, heading });
    const started = performance.now();
    while (performance.now() - started < 20000) {
      await kit.sleep(50);
      const live = challenges.getState();
      if (index === 0 ? live.phase === 'running' : live.phase === 'finished') break;
    }
  }
  await kit.sleep(600);
  const run = finished[0];
  const medals = ctx.systems.journal.getMedals();
  const data = ctx.systems.journal.getData();
  const best = data.challenges?.courses?.[kit.courseKey]?.best?.glider;
  return kit.check('challenges: a finish on the real challenge system shows in the journal with its medal, read from the challenge records', switched && run && run.medal === 'bronze' && run.valid && best && best.medal === 'bronze' && medals.bronze === medalsBefore.bronze + 1 && !('challenges' in (ctx.storage.read('driftwing-v2.records', null) || {})), JSON.stringify({ run, best, medals }));
})()

(() => {
  const kit = window.__journalKit;
  const { ctx, state } = window.DRIFTWING;
  ctx.bus.emitTyped('worldVisited', { seed: 'JOURNAL-P3-W', previous: state.seed, portalId: 'portalRing:journal-step' });
  const visits = ctx.systems.journal.getRecords().worldsVisited;
  const last = visits[visits.length - 1];
  const saved = ctx.storage.read('driftwing-v2.records', null);
  return kit.check('worlds: worldVisited keeps the seed, where from and the portal, saved at once', last && last.seed === 'JOURNAL-P3-W' && last.from === state.seed && saved.worldsVisited.some((visit) => visit.seed === 'JOURNAL-P3-W') && saved.version === 3, JSON.stringify(last));
})()

(async () => {
  const kit = window.__journalKit;
  const { ctx } = window.DRIFTWING;
  ctx.systems.journal.update(0, 6);
  ctx.systems.ui.showPanel('journal');
  await kit.sleep(900);
  const text = kit.text();
  const sections = ['discoveries', 'records', 'craft', 'figures', 'challenges', 'worlds'].filter((id) => kit.section(id));
  const jumps = document.querySelectorAll('#dw-journal-body [data-journal-jump]').length;
  const collection = document.querySelector('#dw-journal-body [data-stat="collection"]')?.textContent ?? '';
  return [
    kit.check('panel: the journal opens with every new section and its jump button', sections.length === 6 && jumps === 6, JSON.stringify({ sections, jumps })),
    kit.check('panel: the collection reads x / 100', /^\d+ \/ 100$/.test(collection), collection),
  ].join(' | ');
})()

(async () => {
